function smallestNumber(num) {
  if (num === 0) {
    return 0;
  }
  const digits = String(Math.abs(num)).split('').map(Number);
  if (num < 0) {
    digits.sort((a, b) => b - a);
    return -Number(digits.join(''));
  }
  digits.sort((a, b) => a - b);
  const firstNonZero = digits.findIndex((digit) => digit !== 0);
  [digits[0], digits[firstNonZero]] = [digits[firstNonZero], digits[0]];
  return Number(digits.join(''));
}

