function smallestNumber(num) {
  const sign = num < 0 ? -1 : 1;
  const text = String(Math.abs(num));
  const counts = Array(10).fill(0);
  for (const ch of text) counts[Number(ch)]++;
  let best = null;
  const build = (prefix) => {
    if (prefix.length === text.length) {
      if (text.length > 1 && prefix[0] === '0') return;
      const value = sign * Number(prefix);
      if (best === null || value < best) best = value;
      return;
    }
    for (let d = 0; d <= 9; d++) {
      if (counts[d] === 0) continue;
      counts[d]--;
      build(prefix + d);
      counts[d]++;
    }
  };
  build('');
  return best;
}

