function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const negative = rand() < 0.5;
  if (size === 'large' && rand() < 0.15) return [negative ? -1e15 : 1e15];
  if (size === 'small' && rand() < 0.08) return [0];
  const length = size === 'large' ? int(12, 15) : int(1, 7);
  const zeroRate = rand() * 0.5;
  let text = '';
  for (let i = 0; i < length; i++) text += rand() < zeroRate ? '0' : String(int(0, 9));
  const value = Number(text);
  return [negative && value !== 0 ? -value : value];
}
